    <tr><th>Code</th><th>Work package</th><th>Responsable</th><th>Période</th><th class="num">Mois</th><th class="num">ETP·mois</th><th class="num">RH</th><th class="num">Prestations</th><th class="num">CAPEX</th><th class="num">Autres</th><th class="num">Total</th></tr>
